import{_ as r,a0 as m,w as l,s,I as a,x as t,a1 as p,A as o,ao as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Linux 小技巧：Chrome 小游戏，让文字说话，计划作业，重复执行命令 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 小技巧：Chrome 小游戏，让文字说话，计划作业，重复执行命令 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 小技巧：Chrome 小游戏，让文字说话，计划作业，重复执行命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 小技巧：Chrome 小游戏，让文字说话，计划作业，重复执行命令 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150812 Linux Tricks--Play Game in Chrome Text-to-Speech Schedule a Job and Watch Commands in Linux","title":"Linux 小技巧：Chrome 小游戏，让文字说话，计划作业，重复执行命令","tag":"201509","desc":""},"relativePath":"201509/20150812 Linux Tricks--Play Game in Chrome Text-to-Speech Schedule a Job and Watch Commands in Linux.md","filePath":"[post].md"}'),d={name:"201509/20150812 Linux Tricks--Play Game in Chrome Text-to-Speech Schedule a Job and Watch Commands in Linux.md"};function u(x,e,h,c,w,C){const n=m("Link");return l(),s("div",null,[e[19]||(e[19]=a("h1",{id:"linux-小技巧-chrome-小游戏-让文字说话-计划作业-重复执行命令",tabindex:"-1"},[t("Linux 小技巧：Chrome 小游戏，让文字说话，计划作业，重复执行命令 "),a("a",{class:"header-anchor",href:"#linux-小技巧-chrome-小游戏-让文字说话-计划作业-重复执行命令","aria-label":"Permalink to “Linux 小技巧：Chrome 小游戏，让文字说话，计划作业，重复执行命令”"},"​")],-1)),a("p",null,[e[1]||(e[1]=t("重要的事情说两遍，我完成了一个",-1)),p(n,{href:"http://www.tecmint.com/tag/linux-tricks/"},{default:o(()=>[...e[0]||(e[0]=[t("Linux提示与彩蛋",-1)])]),_:1}),e[2]||(e[2]=t("系列，让你的Linux获得更多创造和娱乐。",-1))]),e[20]||(e[20]=i(`<p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Linux-Tips-and-Tricks.png" alt="Linux提示与彩蛋系列"></p><p><em>Linux提示与彩蛋系列</em></p><p>本文，我将会讲解Google-chrome内建小游戏，在终端中如何让文字说话，使用‘at’命令设置作业和使用watch命令重复执行命令。</p><h3 id="_1-google-chrome-浏览器小游戏彩蛋" tabindex="-1">1. Google Chrome 浏览器小游戏彩蛋 <a class="header-anchor" href="#_1-google-chrome-浏览器小游戏彩蛋" aria-label="Permalink to “1. Google Chrome 浏览器小游戏彩蛋”">​</a></h3><p>网线脱掉或者其他什么原因连不上网时，Google Chrome就会出现一个小游戏。声明，我并不是游戏玩家，因此我的电脑上并没有安装任何第三方的恶意游戏。安全是第一位。</p><p>所以当Internet发生出错，会出现一个这样的界面：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Unable-to-Connect-Internet.png" alt="不能连接到互联网"></p><p><em>不能连接到互联网</em></p><p>按下空格键来激活Google-chrome彩蛋游戏。游戏没有时间限制。并且还不需要浪费时间安装使用。</p><p>不需要第三方软件的支持。同样支持Windows和Mac平台，但是我的平台是Linux，我也只谈论Linux。当然在Linux，这个游戏运行很好。游戏简单，但也很花费时间。</p><p>使用空格/向上方向键来跳跃。请看下列截图：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Play-Game-in-Google-Chrome.gif" alt="Google Chrome中玩游戏"></p><p><em>Google Chrome中玩游戏</em></p><h3 id="_2-linux-终端中朗读文字" tabindex="-1">2. Linux 终端中朗读文字 <a class="header-anchor" href="#_2-linux-终端中朗读文字" aria-label="Permalink to “2. Linux 终端中朗读文字”">​</a></h3><p>对于那些不能文字朗读的设备，有个小工具可以实现文字说话的转换器。用各种语言写一些东西，espeak就可以朗读给你。</p><p>系统应该默认安装了Espeak，如果你的系统没有安装，你可以使用下列命令来安装：</p><pre><code># apt-get install espeak   (Debian)
# yum install espeak       (CentOS)
# dnf install espeak       (Fedora 22 及其以后)
</code></pre><p>你可以让espeak接受标准输入的交互输入并及时转换成语音朗读出来。如下：</p><pre><code>$ espeak [按回车键]
</code></pre><p>更详细的输出你可以这样做：</p><pre><code>$ espeak --stdout | aplay [按回车键][再次回车]
</code></pre><p>espeak设置灵活，也可以朗读文本文件。你可以这样设置：</p><pre><code>$ espeak --stdout /path/to/text/file/file_name.txt  | aplay [Hit Enter] 
</code></pre><p>espeak可以设置朗读速度。默认速度是160词每分钟。使用-s参数来设置。</p><p>设置每分钟30词的语速：</p><pre><code>$ espeak -s 30 -f /path/to/text/file/file_name.txt | aplay
</code></pre><p>设置每分钟200词的语速：</p><pre><code>$ espeak -s 200 -f /path/to/text/file/file_name.txt | aplay
</code></pre><p>说其他语言，比如北印度语（作者母语），这样设置：</p><pre><code>$ espeak -v hindi --stdout &#39;टेकमिंट विश्व की एक बेहतरीन लाइंक्स आधारित वेबसाइट है|&#39; | aplay 
</code></pre><p>你可以使用各种语言，让espeak如上面说的以你选择的语言朗读。使用下列命令来获得语言列表：</p><pre><code>$ espeak --voices
</code></pre><h3 id="_3-快速调度任务" tabindex="-1">3. 快速调度任务 <a class="header-anchor" href="#_3-快速调度任务" aria-label="Permalink to “3. 快速调度任务”">​</a></h3>`,33)),a("p",null,[e[4]||(e[4]=t("我们已经非常熟悉使用",-1)),p(n,{href:"http://www.tecmint.com/11-cron-scheduling-task-examples-in-linux/"},{default:o(()=>[...e[3]||(e[3]=[t("cron",-1)])]),_:1}),e[5]||(e[5]=t("守护进程执行一个计划命令。",-1))]),e[21]||(e[21]=i(`<p>Cron是一个Linux系统管理的高级命令，用于计划定时任务如备份或者指定时间或间隔的任何事情。</p><p>但是，你是否知道at命令可以让你在指定时间调度一个任务或者命令？at命令可以指定时间执行指定内容。</p><p>例如，你打算在早上11点2分执行uptime命令，你只需要这样做：</p><pre><code>$ at 11:02
uptime &gt;&gt; /home/$USER/uptime.txt 
Ctrl+D
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Schedule-Job-in-Linux.png" alt="Linux中计划任务"></p><p><em>Linux中计划任务</em></p><p>检查at命令是否成功设置，使用：</p><pre><code>$ at -l
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/View-Scheduled-Jobs.png" alt="浏览计划任务"></p><p><em>浏览计划任务</em></p><p>at支持计划多个命令，例如：</p><pre><code>$ at 12:30
Command – 1
Command – 2
…
command – 50
…
Ctrl + D
</code></pre><h3 id="_4-特定时间重复执行命令" tabindex="-1">4. 特定时间重复执行命令 <a class="header-anchor" href="#_4-特定时间重复执行命令" aria-label="Permalink to “4. 特定时间重复执行命令”">​</a></h3><p>有时，我们可以需要在指定时间间隔执行特定命令。例如，每3秒，想打印一次时间。</p><p>查看现在时间，使用下列命令。</p><pre><code>$ date +&quot;%H:%M:%S
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Check-Date-in-Linux.png" alt="Linux中查看日期和时间"></p><p><em>Linux中查看日期和时间</em></p><p>为了每三秒查看一下这个命令的输出，我需要运行下列命令：</p><pre><code>$ watch -n 3 &#39;date +&quot;%H:%M:%S&quot;&#39;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Watch-Command-in-Linux.gif" alt="Linux中watch命令"></p><p><em>Linux中watch命令</em></p><p>watch命令的‘-n’开关设定时间间隔。在上述命令中，我们定义了时间间隔为3秒。你可以按你的需求定义。同样watch 也支持其他命令或者脚本。</p><p>至此。希望你喜欢这个系列的文章，让你的linux更有创造性，获得更多快乐。所有的建议欢迎评论。欢迎你也看看其他文章，谢谢。</p><hr>`,25)),a("p",null,[e[7]||(e[7]=t("via: ",-1)),p(n,{href:"http://www.tecmint.com/text-to-speech-in-terminal-schedule-a-job-and-watch-commands-in-linux/"},{default:o(()=>[...e[6]||(e[6]=[t("http://www.tecmint.com/text-to-speech-in-terminal-schedule-a-job-and-watch-commands-in-linux/",-1)])]),_:1})]),a("p",null,[e[11]||(e[11]=t("作者：",-1)),p(n,{href:"http://www.tecmint.com/author/avishek/"},{default:o(()=>[...e[8]||(e[8]=[t("Avishek Kumar",-1)])]),_:1}),e[12]||(e[12]=t(" 译者：",-1)),p(n,{href:"http://vicyu.net"},{default:o(()=>[...e[9]||(e[9]=[t("VicYu/Vic020",-1)])]),_:1}),e[13]||(e[13]=t(" 校对：",-1)),p(n,{href:"https://github.com/wxy"},{default:o(()=>[...e[10]||(e[10]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[16]||(e[16]=t("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[14]||(e[14]=[t("LCTT",-1)])]),_:1}),e[17]||(e[17]=t(" 原创翻译，",-1)),p(n,{href:"https://linux.cn/"},{default:o(()=>[...e[15]||(e[15]=[t("Linux中国",-1)])]),_:1}),e[18]||(e[18]=t(" 荣誉推出",-1))])])}const g=r(d,[["render",u]]);export{T as __pageData,g as default};
